 safety='Use practice or consented data only. This course is not legal advice: confirm duties with a qualified adviser in your place.',
 mods=[
 ('What personal data is', 'Any detail that can identify a person, alone or with other details.', ['Names, phone numbers, photos, IDs, locations and online IDs.', 'Sensitive data: health, beliefs, money, children, biometrics.', 'Anonymous data cannot be traced back; pseudonymous can.', 'People have rights over their data.'], 'A sports club list with name, age and allergy: the allergy makes it sensitive.', 'List ten data items from daily life and class each.', 'Each item classed with a reason.'),
 ('Principles', 'Seven ideas guide most privacy laws.', ['Lawful, fair and clear use.', 'Collect for a purpose; collect only what you need.', 'Keep it accurate and only as long as needed.', 'Keep it safe and be able to show what you did.'], 'A form asks for date of birth but only needs "over 18". Change the field to a tick box.', 'Review one real form and remove unneeded fields.', 'Form shortened with reasons.'),
 ('Map the data', 'You cannot protect data you cannot find.', ['List systems: paper, email, shared drives, apps, phones.', 'For each: data kinds, people, purpose, who sees it, where stored, how long kept.', 'Include suppliers who handle data for you.', 'Mark transfers to other countries.'], 'A school keeps scanned IDs in a staff email folder for six years; purpose unclear: flag for deletion.', 'Build a data map with at least 8 rows.', 'All rows complete; owners named.'),
 ('Risk and decisions', 'Score what could go wrong and act on the top items.', ['Risk = chance times harm, each 1 to 5.', 'Fix the top three first: delete, restrict, encrypt.', 'Record decisions and who made them.', 'Check suppliers\' promises.'], 'Unlocked cabinet of staff files: chance 3, harm 4, score 12. Control: lock, key log.', 'Score ten data risks and fix three.', 'Fixes recorded with dates.'),
 ('Notices and consent', 'People should know what happens to their data.', ['Notice in short plain words: who, why, how long, rights, contact.', 'Consent must be clear and easy to withdraw.', 'Do not tie consent to unrelated services.', 'Children need extra care.'], 'A newsletter box is pre-ticked: change to unticked with a clear label.', 'Write a one-page notice and a consent line.', 'Reading level suits a 12-year-old.'),
 ('Requests from people', 'People can ask to see, fix or delete their data.', ['Verify who is asking without collecting more than needed.', 'Search all systems from the data map.', 'Reply within your legal deadline.', 'Keep a log of requests and outcomes.'], 'A request arrives on day 2; the deadline is 30 days; reply drafted on day 9 with the data and a note on what was withheld and why.', 'Answer a mock request in time.', 'Reply complete; log updated.'),
 ('Security and breaches', 'Basic safety stops most leaks; a plan limits harm.', ['Passwords, second step, updates, encryption on phones and laptops.', 'Breach plan: stop, assess, tell, learn.', 'Know when and whom to tell in your place.', 'Practise once a year.'], 'A laptop is lost: encrypted, so risk is low; log the event and replace the device.', 'Write a breach plan and test it with a scenario.', 'Plan names an owner and a deadline.'),
 ('Review and keep it going', 'Privacy is a habit.', ['Quarterly review: new systems, new suppliers, new staff.', 'Short training for all staff.', 'Keep records of training.', 'Plan the next 90 days.'], 'New app joins in March; the review adds it to the data map and checks its terms.', 'Run a mock audit and plan.', 'Audit finds fixes with dates.')],
 quiz=[('What is personal data?', 'Any detail that can identify a person, alone or with other details.'), ('Name a sensitive data type.', 'Health, beliefs, money, children or biometrics.'), ('What is data minimisation?', 'Collecting only what you need.'), ('Why map data?', 'You cannot protect or delete what you cannot find.'), ('How is risk scored?', 'Chance times harm.'), ('What makes consent valid?', 'Clear, informed, free and easy to withdraw.'), ('What must a notice say?', 'Who, why, how long, rights and contact.'), ('What is a request log for?', 'Proving you answered in time.'), ('First step in a breach?', 'Stop the leak and assess.'), ('Is this course legal advice?', 'No; confirm with a qualified adviser.')],
 rubric=[('Data map', 'All systems listed', 'Suppliers and transfers included'), ('Risk work', 'Top three fixed', 'All high risks closed with dates'), ('Notice and consent', 'Plain notice written', 'Tested with a real reader'), ('Requests', 'Mock request answered in time', 'Process tested twice'), ('Breach plan', 'Owner and steps named', 'Scenario drill done')],
